  o+=`<g transform="translate(50 52.6) scale(1.36 1.09) translate(-50 -55.5)">${outfit2(p,k+'t2',s)}</g>`;
  o+=`<defs><clipPath id="${k}t2"><path d="M23 100V71Q23 58 36 55.5H64Q77 58 77 71V100Z"/></clipPath></defs>`;
  o+=`<g clip-path="url(#${k}t)"><path d="M58 51H68Q87 60 87 77V100H61Q64 80 58 51Z" fill="${shade(p.shirt,-.5)}" fill-opacity=".18"/><path d="M15 72Q18 61 30 57.4L29 65Q20 67 15 72Z" fill="#fff" fill-opacity=".08"/>
    <path d="M30 74q2.6 4 .8 9.4M70 74q-2.6 4-.8 9.4" stroke="${OL}" stroke-opacity=".22" stroke-width=".7" fill="none" stroke-linecap="round"/></g>`;
